const DATASET_URL = '';
const OUTPUT_DIR = path.join(__dirname, 'app');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'DuetQA-Verified-multilingual.jsonl');
const CHECKPOINT_FILE = path.join(OUTPUT_DIR, 'checkpoint.json');
const TEMP_DATASET = path.join(os.tmpdir(), 'DuetQA-Verified.jsonl');

function downloadFile(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest);
    https.get(url, response => {
      if (response.statusCode !== 200) {
        reject(new Error(`HTTP ${response.statusCode}`));
        return;
      }
      response.pipe(file);
      file.on('finish', () => {
        file.close();
        resolve();
      });
    }).on('error', err => {
      fs.unlink(dest, () => {});
      reject(err);
    });
  });
}

function loadCheckpoint() {
  if (fs.existsSync(CHECKPOINT_FILE)) {
    try {
      const data = fs.readFileSync(CHECKPOINT_FILE, 'utf8');
      return JSON.parse(data);
    } catch (e) {
      return { processed: 0 };
    }
  }
  return { processed: 0 };
}

function saveCheckpoint(checkpoint) {
  fs.writeFileSync(CHECKPOINT_FILE, JSON.stringify(checkpoint, null, 2), 'utf8');
}

async function translateText(question, answer, language, apiKey, isHungarian) {
  const client = new Cerebras({ apiKey });
  const model = isHungarian ? MODEL_GPT : MODEL_QWEN;

  const systemPrompt = `Te vagy a világ legpontosabb, legmagasabb minőségű nyelvfordítója. A fordításaid anyanyelvi szintűek, természetesek, grammatikailag hibátlanok és kontextusban pontosak. Soha ne adj hozzá magyarázatot, csak a tiszta fordítást add vissza JSON formátumban.`;

  const userPrompt = `Fordítsd le a következő kérdés-válasz párost ${language} nyelvre. A fordítás legyen anyanyelvi szintű, természetes és precíz.

Eredeti kérdés: ${question}
Eredeti válasz: ${answer}

Add vissza a fordítást tiszta JSON formátumban, pontosan így: {"question":"lefordított kérdés","answer":"lefordított válasz"}`;

  try {
    const completion = await client.chat.completions.create({
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      model: model,
      max_completion_tokens: isHungarian ? 65536 : 40000,
      temperature: 0.04,
      top_p: 0.02,
      stream: false
    });

    let content = completion.choices[0].message.content;

    content = content.replace(/``````\n?/g, '').trim();

    let parsed;
    try {
      parsed = JSON.parse(content);
    } catch (parseError) {
      const jsonMatch = content.match(/\{[^}]+\}/);
      if (jsonMatch) {
        parsed = JSON.parse(jsonMatch[0]);
      } else {
        parsed = { question: content, answer: content };
      }
    }

    return {
      question: parsed.question || content,
      answer: parsed.answer || content
    };
  } catch (error) {
    console.error(`Hiba a fordítás során (${language}):`, error.message);
    return {
      question: question,
      answer: answer,
      error: error.message
    };
  }
}

async function processDataset() {
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  console.log('Dataset letöltése...');
  if (!fs.existsSync(TEMP_DATASET)) {
    await downloadFile(DATASET_URL, TEMP_DATASET);
  }
  console.log('Dataset letöltve.');

  const checkpoint = loadCheckpoint();
  let currentIndex = 0;

  const fileStream = fs.createReadStream(TEMP_DATASET);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const writeStream = fs.createWriteStream(OUTPUT_FILE, { flags: 'a' });

  let apiKeyIndex = 0;

  for await (const line of rl) {
    if (!line.trim()) {
      continue;
    }

    if (currentIndex < checkpoint.processed) {
      currentIndex++;
      continue;
    }

    let originalData;
    try {
      originalData = JSON.parse(line);
    } catch (parseError) {
      console.error(`JSON parse hiba a ${currentIndex}. sorban:`, parseError.message);
      currentIndex++;
      continue;
    }

    const question = originalData.question || '';
    const answer = originalData.answer || '';

    if (!question || !answer) {
      currentIndex++;
      continue;
    }

    console.log(`Feldolgozás: ${currentIndex + 1}. elem`);

    const translations = {};

    for (let i = 0; i < LANGUAGES.length; i++) {
      const language = LANGUAGES[i];
      const isHungarian = language === 'magyar';
      const apiKey = API_KEYS[apiKeyIndex % API_KEYS.length];

      console.log(`  Fordítás: ${language}`);

      const translated = await translateText(question, answer, language, apiKey, isHungarian);
      translations[language] = translated;

      apiKeyIndex++;

      await new Promise(resolve => setTimeout(resolve, 250));
    }

    const result = {
      original: {
        question: question,
        answer: answer
      },
      translations: translations
    };

    writeStream.write(JSON.stringify(result) + '\n');

    currentIndex++;
    checkpoint.processed = currentIndex;
    saveCheckpoint(checkpoint);

    await new Promise(resolve => setTimeout(resolve, 500));
  }

  writeStream.end();
  console.log('Feldolgozás befejezve.');
}

processDataset().catch(error => {
  console.error('Kritikus hiba:', error);
  process.exit(1);
});
